ProjectDescriptionContext.declarationTypeText:
{
    /** 上下文来源节点 ID。 */
    nodeId: string;
    /** 上下文来源节点标题。 */
    title: string;
    /** 上下文来源节点类型。 */
    nodeKind: string;
    /** 上下文来源节点描述文本。 */
    description: string;
}

NavContextItem.declarationTypeText:
{
    /** 选项稳定值，会写入导航上下文状态。 */
    id: string | number;
    /** 选项展示标题。 */
    title: string;
}

NavContextConfig.declarationTypeText:
{
    /** 上下文选项来源；字符串表示远端/命名来源，数组表示内联静态选项。 */
    source: string | NavContextItem[];
    /** 上下文未选择时的占位提示。 */
    placeholder?: string | undefined;
    /** 上下文默认选中值。 */
    defaultValue?: string | number | undefined;
    /** 写入路由或查询参数时使用的参数名。 */
    paramName?: string | undefined;
}

ProjectNodeData.declarationTypeText:
{
    /** 导航节点唯一 ID。 */
    id: string;
    /** 导航节点标题。 */
    title: string;
    /** 节点业务描述，供 AI 策划和页面设计理解用途。 */
    description?: string | undefined;
    /** 节点策划详细说明附件引用；正文由工作区解析后传给 LLM。 */
    planningAttachmentRef?: string | undefined;
    /** 节点版本号或版本标签。 */
    version?: string | undefined;
    /** 节点图标名。 */
    icon?: string | undefined;
    /** 导航节点类型，决定页面、模块、链接、引用等行为。 */
    nodeKind?: NavNodeKind | undefined;
    /** 子节点在应用壳中的布局区域。 */
    childPlacement?: ChildPlacement | undefined;
    /** 导航上下文配置或静态上下文选项。 */
    context?: string | NavContextItem[] | NavContextConfig | undefined;
    /** 同级排序值，数值越小越靠前。 */
    order?: number | undefined;
    /** 是否在导航中隐藏。 */
    hidden?: boolean | undefined;
    /** 是否禁用该导航节点。 */
    disabled?: boolean | undefined;
    /** 是否在该节点后显示分隔线。 */
    dividerAfter?: boolean | undefined;
    /** 权限不匹配时的展示策略。 */
    permissionMode?: NavPermissionMode | undefined;
    /** 子导航节点。 */
    children?: ProjectNodeData[] | undefined;
    /** 页面路由路径。 */
    path?: string | undefined;
    /** link 节点的打开目标。 */
    linkTarget?: 'iframe' | 'new-tab' | 'self' | undefined;
    /** 重定向目标路径。 */
    redirect?: string | undefined;
    /** ref 节点引用的目标节点 ID。 */
    refId?: string | undefined;
    /** ref 节点解析后的目标路径。 */
    refPath?: string | undefined;
    /** ref 节点引用的目标项目 ID。 */
    refProjectId?: string | undefined;
    /** ref 引用是否已失效。 */
    refBroken?: boolean | undefined;
    /** pageDesign 实现放行闸门；缺省过渡期为 open。 */
    implGate?: 'closed' | 'open' | undefined;
    /** 上游 iPaaS / 契约就绪；缺省 true。 */
    upstreamContractsSatisfied?: boolean | undefined;
}

ProjectNodeNavigationPatch.declarationTypeText:
{
    /** 新标题。 */
    title: string;
    /** 新节点类型。 */
    nodeKind?: NavNodeKind | undefined;
    /** 新图标名。 */
    icon?: string | undefined;
    /** 是否在节点后显示分隔线。 */
    dividerAfter?: boolean | undefined;
    /** 新节点描述。 */
    description?: string | undefined;
    /** 新策划详细说明附件引用。 */
    planningAttachmentRef?: string | undefined;
    /** 新路由路径。 */
    path?: string | undefined;
    /** link 节点新打开目标。 */
    linkTarget?: string | undefined;
    /** 新子节点布局区域。 */
    childPlacement?: string | undefined;
    /** 新同级排序值。 */
    order?: number | undefined;
    /** 是否隐藏节点。 */
    hidden?: boolean | undefined;
    /** 是否禁用节点。 */
    disabled?: boolean | undefined;
    /** 新 ref 目标节点 ID。 */
    refId?: string | undefined;
    /** 新权限展示策略。 */
    permissionMode?: NavPermissionMode | undefined;
    /** 新导航上下文配置。 */
    context?: string | NavContextItem[] | NavContextConfig | undefined;
    /** 新 pageDesign 实现放行闸门。 */
    implGate?: 'closed' | 'open' | undefined;
    /** 新上游契约就绪状态。 */
    upstreamContractsSatisfied?: boolean | undefined;
}

ProjectNodeLocation.declarationTypeText:
{
    /** 命中的节点数据。 */
    node: ProjectNodeData;
    /** 父节点数据；根节点无父级时为 null。 */
